let DATA=null, projects=[], p=null, result=null, step=0, selectedRoom=null, selectedPlanObject=null, dirty=false, history=[], future=[];
const appEl=document.getElementById('app');
const money=n=>'Rp'+Math.round(n||0).toLocaleString('id-ID');
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const uuid=()=>window.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(16).slice(2);
const snapshot=()=>p?JSON.stringify(p):null;
function markEdit(){
  if(!p)return;
  const snap=snapshot();
  if(!history.length||history[history.length-1]!==snap)history.push(snap);
  if(history.length>60)history.shift();
  future=[];dirty=true;
}
function undoEdit(){if(!p||!history.length)return;const cur=snapshot();future.push(cur);const snap=history.pop();p=normalize(JSON.parse(snap));dirty=true;selectedRoom=null;render();}
function redoEdit(){if(!p||!future.length)return;const cur=snapshot();history.push(cur);const snap=future.pop();p=normalize(JSON.parse(snap));dirty=true;selectedRoom=null;render();}
function setDirty(v=true){dirty=!!v;document.querySelectorAll('[data-dirty-indicator]').forEach(x=>x.textContent=dirty?'● Belum disimpan':'✓ Tersimpan');}

const roomNames={bedroom:'Kamar Tidur',bathroom:'Kamar Mandi',living:'Ruang Tamu',family:'Ruang Keluarga',kitchen:'Dapur',dining:'Ruang Makan',storage:'Gudang',laundry:'Laundry',mosque:'Mushola',terrace:'Teras',carport:'Carport'};
const roomIcons={bedroom:'🛏️',bathroom:'🚿',living:'🛋️',family:'📺',kitchen:'🍳',dining:'🍽️',storage:'📦',laundry:'🧺',mosque:'🕌',terrace:'🌿',carport:'🚗'};
const roofNames={pelana:'Pelana',limas:'Limas',datar:'Datar'};
function defaults(){return {schemaVersion:3,id:uuid(),name:'Rumah Baru',owner:'',location:'',note:'',houseType:'36',land:{length:10,width:15},building:{area:36,length:6,width:6,floors:1,wallHeight:3,roofPitch:30,overhang:.5,bedrooms:2,bathrooms:1,terraceArea:5,carportArea:12,openings:{doors:4,windows:5,doorWidth:.9,doorHeight:2.1,windowWidth:1.2,windowHeight:1.2}},spec:{wall:'lightbrick',floor:'tile',roofCover:'genteng',ceiling:'gypsum'},waste:{material:5,tile:7,brick:5,paint:5,roof:5},materialWaste:{},coefficients:{},extras:{equipment:5,overhead:5,contingency:5,transport:0,profit:0},laborPriceOverrides:{},budget:{mode:'estimate',availableFunds:0,minimizeSuggestions:true},priceOverrides:{},visual:{colors:{wall:'#E8E4DC',roof:'#8E4436',door:'#5B4030',trim:'#4D4037',window:'#77B8D0',floor:'#D9C9AD',fence:'#5B5148',terrace:'#C9B69A'},preset:'custom'},rooms:[],doors:[],windows:[],partitions:[]};}
function makeRooms(b){const r=[];const add=(type,name,w,h,x,y)=>r.push({id:uuid(),type,name:name||roomNames[type],x,y,width:w,height:h});let x=0,y=0;const L=b.length,W=b.width;const bw=Math.min(3.5,L*.38), bh=Math.min(3.2,W*.48); for(let i=0;i<b.bedrooms;i++){const xx=(i%2)*bw, yy=Math.floor(i/2)*bh; add('bedroom',roomNames.bedroom+' '+(i+1),bw,bh,xx,yy);} add('living','Ruang Tamu',Math.min(3.8,L*.42),Math.min(3.2,W*.48),Math.min(bw*2,L*.5),0); add('kitchen','Dapur',Math.min(3.2,L*.35),Math.min(2.8,W*.4),Math.min(bw*2,L*.5),Math.min(3.2,W*.5)); for(let i=0;i<b.bathrooms;i++) add('bathroom',roomNames.bathroom+' '+(i+1),1.8,2,Math.max(0,L-1.9),Math.max(0,W-2.1-i*2.1)); add('terrace','Teras',Math.min(3.5,L*.5),1.5,Math.max(0,(L-3.5)/2),Math.max(0,W-1.5)); return r;}
function normalize(x){const d=defaults(); x={...d,...x,building:{...d.building,...(x.building||{}),openings:{...d.building.openings,...(x.building?.openings||{})}},land:{...d.land,...(x.land||{})},spec:{...d.spec,...(x.spec||{})},waste:{...d.waste,...(x.waste||{})},extras:{...d.extras,...(x.extras||{})},laborPriceOverrides:{...(x.laborPriceOverrides||{})},budget:{...d.budget,...(x.budget||{})},priceOverrides:{...(x.priceOverrides||{})},materialWaste:{...(x.materialWaste||{})},coefficients:{...(x.coefficients||{})},visual:{...d.visual,...(x.visual||{}),colors:{...d.visual.colors,...(x.visual?.colors||{})}}};
 if(!x.rooms?.length)x.rooms=makeRooms(x.building);
 const L=+x.building.length||6,W=+x.building.width||6,o=x.building.openings||{};
 if(!Array.isArray(x.doors)||!x.doors.length)x.doors=Array.from({length:Math.max(1,+o.doors||1)},(_,i)=>({id:`door-${String(i+1).padStart(3,'0')}`,type:'door',wallId:'wall-front',offset:L*(i+1)/(Math.max(1,+o.doors||1)+1),width:+o.doorWidth||.9,height:+o.doorHeight||2.1,sillHeight:0,rotation:0}));
 if(!Array.isArray(x.windows)||!x.windows.length)x.windows=Array.from({length:Math.max(2,+o.windows||2)},(_,i)=>({id:`window-${String(i+1).padStart(3,'0')}`,type:'window',wallId:'wall-front',offset:L*(i+1)/(Math.max(2,+o.windows||2)+1),width:+o.windowWidth||1.2,height:+o.windowHeight||1.2,sillHeight:1,rotation:0}));
 if(!Array.isArray(x.partitions))x.partitions=[];
 x.roofType=['pelana','limas','datar'].includes(x.roofType)?x.roofType:'pelana';
 x.building.length=Math.max(3,Number(x.building.length)||6);x.building.width=Math.max(3,Number(x.building.width)||6);
 x.building.openings.doors=x.doors.length;x.building.openings.windows=x.windows.length;
 x.schemaVersion=3; return x;}
function fresh(){p=defaults();step=0;selectedRoom=null;history=[];future=[];dirty=true;p.rooms=makeRooms(p.building);render();}
async function recalc(){if(!p)return null;try{result=await window.api.calc(p);const badge=document.getElementById('totalBadge');if(badge)badge.textContent=money(result.summary.total);return result;}catch(e){console.error('RAB calc failed',e);toast('Perhitungan RAB gagal. Periksa data proyek.');return null;}}
async function save(silent=true){if(!p)return false;const r=await recalc();if(!r)return false;try{p._total=r.summary.total;p.updatedAt=new Date().toISOString();await window.api.save(p);setDirty(false);if(!silent)toast('Proyek tersimpan.');return true;}catch(e){console.error('Save failed',e);toast('Gagal menyimpan proyek.');return false;}}
function toast(s){const d=document.createElement('div');d.className='toast';d.textContent=s;document.body.appendChild(d);setTimeout(()=>d.remove(),1800)}
function shell(title,sub,body){document.getElementById('title').textContent=title;document.getElementById('subtitle').textContent=sub;appEl.innerHTML=`<div class="container"><div class="stepper">${['Data Proyek','Denah & Dimensi','Spesifikasi','Material & Harga','RAB Detail','Maket 3D','Laporan'].map((x,i)=>`<button class="step ${i===step?'active':''}" data-action="gotoStep" data-arg="${i}">${i+1}. ${x}</button>`).join('')}</div>${body}</div>`;}
let renderSeq=0; async function render(){const seq=++renderSeq;if(!p){renderHome();return;} await recalc();if(seq!==renderSeq||!p)return; if(step===0)renderProject();else if(step===1)renderPlan();else if(step===2)renderSpecs();else if(step===3)renderMaterials();else if(step===4)renderRab();else if(step===5)render3D();else renderReport();}
function renderHome(){document.getElementById('title').textContent='RAB Rumahku';document.getElementById('subtitle').textContent='Perencanaan rumah, visual maket, kebutuhan bahan, dan RAB dalam satu proyek.';document.getElementById('totalBadge').textContent='Rp0';appEl.innerHTML=`<div class="container"><div class="hero"><div><span class="eyebrow">VERSI PRO</span><h2>Rancang rumah dari denah sampai RAB.</h2><p>Geometri bangunan menjadi sumber perhitungan volume, kebutuhan material, biaya tenaga kerja, dan visual maket 3D.</p><div class="hero-pills"><span>📐 Denah terukur</span><span>🧱 Material realistis</span><span>💰 RAB transparan</span><span>🏠 Maket 3D</span></div></div><button class="primary big" data-action="fresh">＋ BUAT PROYEK</button></div><div class="section-head"><h2>Proyek Terakhir</h2><button class="secondary" data-action="projects">Lihat semua</button></div><div class="grid">${projects.length?projects.slice(0,6).map(x=>`<div class="card project-card"><div class="project-icon">🏠</div><h3>${esc(x.name)}</h3><div class="muted">${esc(x.location||'Lokasi belum diisi')} · Tipe ${esc(x.houseType||'-')}</div><div class="price">${money(x._total||0)}</div><button class="secondary full" data-action="openProject" data-arg="${x.id}">Buka proyek</button></div>`).join(''):'<div class="card empty">Belum ada proyek. Buat proyek pertama Anda.</div>'}</div><div class="info-grid"><div class="info-card"><b>📐 Satu sumber data</b><span>Ukuran denah, volume, material, dan visual menggunakan parameter proyek yang sama.</span></div><div class="info-card"><b>🧾 RAB dapat diaudit</b><span>Setiap pekerjaan menampilkan volume, satuan, harga, waste, dan subtotal.</span></div><div class="info-card"><b>⚠️ Estimasi konstruksi</b><span>Harga dan koefisien adalah referensi yang dapat disesuaikan dengan lokasi serta spesifikasi.</span></div></div></div>`;}
function renderProject(){const b=p.building,o=b.openings; shell('Data Proyek','Tetapkan ukuran bangunan yang menjadi dasar seluruh perhitungan.',`<div class="card"><div class="section-head"><div><h2>Identitas Proyek</h2><p class="muted">Data ini muncul di laporan dan ekspor.</p></div></div><div class="formgrid"><Field id="name" label="Nama proyek" value={p.name}/><Field id="owner" label="Pemilik" value={p.owner}/><Field id="location" label="Lokasi proyek" value={p.location}/><Field id="note" label="Catatan" value={p.note} area/></div></div><div class="card"><h2>Dimensi Bangunan</h2><div class="formgrid four"><Field id="bl" label="Panjang bangunan (m)" value={b.length} num/><Field id="bw" label="Lebar bangunan (m)" value={b.width} num/><Field id="floors" label="Jumlah lantai" value={b.floors} num/><Field id="wallHeight" label="Tinggi dinding (m)" value={b.wallHeight} num/><Field id="roofPitch" label="Kemiringan atap (°)" value={b.roofPitch} num/><Field id="overhang" label="Overstek atap (m)" value={b.overhang} num/><Field id="terrace" label="Luas teras (m²)" value={b.terraceArea} num/><Field id="carport" label="Luas carport (m²)" value={b.carportArea} num/></div><div class="live-stat">Luas lantai terhitung <b>${(b.length*b.width*b.floors).toFixed(2)} m²</b></div></div><div class="card"><h2>Jumlah Bukaan</h2><div class="formgrid four"><Field id="doors" label="Jumlah pintu" value={o.doors} num/><Field id="windows" label="Jumlah jendela" value={o.windows} num/><Field id="doorWidth" label="Lebar pintu (m)" value={o.doorWidth} num/><Field id="doorHeight" label="Tinggi pintu (m)" value={o.doorHeight} num/><Field id="windowWidth" label="Lebar jendela (m)" value={o.windowWidth} num/><Field id="windowHeight" label="Tinggi jendela (m)" value={o.windowHeight} num/></div><div class="actions"><button class="primary" data-action="applyProject">Simpan & lanjut →</button></div></div>`)}
function Field({id,label,value,num=false,area=false}){return `<div class="field"><label>${label}</label>${area?`<textarea id="${id}">${esc(value)}</textarea>`:`<input id="${id}" ${num?'type="number" step="0.1" min="0"':''} value="${esc(value)}">`}</div>`}
async function applyProject(){const g=id=>document.getElementById(id);p.name=g('name').value.trim()||'Rumah Baru';p.owner=g('owner').value.trim();p.location=g('location').value.trim();p.note=g('note').value.trim();p.building={...p.building,length:+g('bl').value||6,width:+g('bw').value||6,floors:Math.max(1,Math.round(+g('floors').value||1)),wallHeight:+g('wallHeight').value||3,roofPitch:+g('roofPitch').value||30,overhang:+g('overhang').value||.5,terraceArea:+g('terrace').value||0,carportArea:+g('carport').value||0,openings:{...p.building.openings,doors:+g('doors').value||1,windows:+g('windows').value||2,doorWidth:+g('doorWidth').value||.9,doorHeight:+g('doorHeight').value||2.1,windowWidth:+g('windowWidth').value||1.2,windowHeight:+g('windowHeight').value||1.2}};p.building.area=p.building.length*p.building.width*p.building.floors;p.houseType='custom';if(!p.rooms.length)p.rooms=makeRooms(p.building);await save();step=1;render();}
function renderPlan(){
 const b=p.building,scale=Math.min(78,820/Math.max(b.length,b.width,1)),pw=Math.max(420,b.length*scale),ph=Math.max(300,b.width*scale);
 const roomEls=p.rooms.map(r=>{const left=r.x*scale,top=r.y*scale,w=r.width*scale,h=r.height*scale;return `<div class="room ${selectedRoom===r.id?'selected':''}" data-room-id="${r.id}" style="left:${left}px;top:${top}px;width:${w}px;height:${h}px"><span>${roomIcons[r.type]||'▧'}<br>${esc(r.name)}</span></div>`}).join('');
 const wallT=6;
 const openingEls=[...(p.doors||[]),...(p.windows||[])].map(o=>{const horizontal=!String(o.wallId||'').includes('left')&&!String(o.wallId||'').includes('right');const front=o.wallId==='wall-front';const w=Math.max(8,(+o.width||1)*scale),h=horizontal?wallT:Math.max(8,(+o.width||1)*scale);const left=horizontal?((+o.offset||0)*scale-w/2):((o.wallId==='wall-left'?0:b.length*scale)-wallT/2);const top=horizontal?(front?-wallT/2:ph-wallT/2):((+o.offset||0)*scale-h/2);return `<div class="plan-opening ${o.type} ${selectedPlanObject?.id===o.id?'selected':''}" data-plan-object="${o.type}:${o.id}" title="${o.type==='door'?'Pintu':'Jendela'}" style="left:${left}px;top:${top}px;width:${w}px;height:${h}px"></div>`}).join('');
 const partEls=(p.partitions||[]).map(q=>{const vertical=q.axis==='y',len=Math.max(.6,+q.length||2)*scale,left=(+q.x||0)*scale-(vertical?wallT/2:len/2),top=(+q.y||0)*scale-(vertical?len/2:wallT/2),w=vertical?wallT:len,h=vertical?len:wallT;return `<div class="plan-partition ${selectedPlanObject?.id===q.id?'selected':''}" data-plan-object="partition:${q.id}" style="left:${left}px;top:${top}px;width:${w}px;height:${h}px"></div>`}).join('');
 shell('Denah & Dimensi','Editor 2D terhubung ke House Model. Seret ruangan, pintu, jendela, atau sekat; perubahan disimpan dalam koordinat meter.',`<div class="card"><div class="toolbar"><div><b>Bangunan ${b.length} × ${b.width} m</b><div class="muted">${b.floors} lantai · ${b.length*b.width*b.floors} m² lantai</div></div><div class="button-row">${Object.keys(roomNames).map(t=>`<button class="chip" data-action="addRoom" data-arg="${t}">${roomIcons[t]} ${roomNames[t]}</button>`).join('')}</div><div class="button-row"><button class="chip" data-action="add3DDoor">＋ Pintu</button><button class="chip" data-action="add3DWindow">＋ Jendela</button><button class="chip" data-action="addPartition">＋ Sekat</button><span data-dirty-indicator class="muted">${dirty?'● Belum disimpan':'✓ Tersimpan'}</span><button class="secondary" data-action="undo">↶ Undo</button><button class="secondary" data-action="redo">↷ Redo</button><button class="primary" data-action="saveProject">💾 Simpan Perubahan</button></div></div><div class="plan-scroll"><div class="plan" id="plan" style="width:${pw}px;height:${ph}px">${roomEls}${openingEls}${partEls}<div class="plan-dim top">${b.length.toFixed(2)} m</div><div class="plan-dim side">${b.width.toFixed(2)} m</div></div></div></div>${selectedRoom?roomEditor():`<div class="card hint"><b>Tip:</b> Klik ruangan untuk mengubah nama/ukuran. Klik atau seret pintu, jendela, dan sekat untuk mengedit objek yang sama dengan model 3D.</div>`}${selectedPlanObject?planObjectEditor():''}<div class="actions"><button class="secondary" data-action="gotoStep" data-arg="0">← Data Proyek</button><button class="primary" data-action="gotoStep" data-arg="2">Lanjut ke Spesifikasi →</button></div>`);
}
function planObjectEditor(){const info=selectedPlanObject;if(!info)return '';const arr=info.type==='door'?p.doors:info.type==='window'?p.windows:p.partitions,q=arr.find(x=>x.id===info.id);if(!q)return '';if(info.type==='partition')return `<div class="card"><h3>✚ Edit Sekat</h3><div class="formgrid four"><Field id="poX" label="X (m)" value={q.x} num/><Field id="poY" label="Y (m)" value={q.y} num/><Field id="poLen" label="Panjang (m)" value={q.length} num/><div class="field"><label>Arah</label><select id="poAxis"><option value="x" ${q.axis==='x'?'selected':''}>Horizontal</option><option value="y" ${q.axis==='y'?'selected':''}>Vertikal</option></select></div></div><div class="actions"><button class="primary" data-action="applyPlanPartition">Simpan</button><button class="danger" data-action="deletePartition">Hapus</button></div></div>`;return `<div class="card"><h3>${info.type==='door'?'🚪 Pintu':'🪟 Jendela'}</h3><div class="formgrid four"><div class="field"><label>Dinding</label><select id="poWall">${['wall-front','wall-back','wall-left','wall-right'].map(id=>`<option value="${id}" ${q.wallId===id?'selected':''}>${id.replace('wall-','')}</option>`).join('')}</select></div><Field id="poOffset" label="Posisi sepanjang dinding (m)" value={q.offset} num/><Field id="poWidth" label="Lebar (m)" value={q.width} num/><Field id="poHeight" label="Tinggi (m)" value={q.height} num/>${info.type==='window'?`<Field id="poSill" label="Ambang (m)" value={q.sillHeight} num/>`:''}</div><div class="actions"><button class="primary" data-action="applyPlanOpening">Simpan</button><button class="danger" data-action="deletePlanOpening">Hapus</button></div></div>`;}
function roomEditor(){const r=p.rooms.find(x=>x.id===selectedRoom);if(!r)return '';return `<div class="card"><div class="section-head"><h2>${roomIcons[r.type]} Edit Ruangan</h2><button class="danger" data-action="deleteRoom">Hapus</button></div><div class="formgrid four"><Field id="rn" label="Nama" value={r.name}/><div class="field"><label>Jenis</label><select id="rt">${Object.entries(roomNames).map(([k,v])=>`<option value="${k}" ${r.type===k?'selected':''}>${v}</option>`).join('')}</select></div><Field id="rx" label="Posisi X (m)" value={r.x} num/><Field id="ry" label="Posisi Y (m)" value={r.y} num/><Field id="rw" label="Panjang (m)" value={r.width} num/><Field id="rh" label="Lebar (m)" value={r.height} num/><div class="field"><label>Luas</label><div class="metric" style="padding:9px">${(r.width*r.height).toFixed(2)} m²</div></div></div><div class="actions"><button class="primary" data-action="updateRoom">Terapkan perubahan</button></div></div>`}
function addRoom(type){const b=p.building;markEdit();const idx=p.rooms.length;const w=type==='bathroom'?1.8:type==='carport'?3:type==='terrace'?3.5:3;const h=type==='bathroom'?2:type==='terrace'?1.5:3; p.rooms.push({id:uuid(),type,name:`${roomNames[type]} ${type==='bedroom'||type==='bathroom'?p.rooms.filter(r=>r.type===type).length+1:''}`.trim(),x:Math.min(Math.max(0,b.length-w),idx%3*3),y:Math.min(Math.max(0,b.width-h),Math.floor(idx/3)*3),width:w,height:h});selectedRoom=p.rooms.at(-1).id;dirty=true;recalc();renderPlan();}
function updateRoom(){const r=p.rooms.find(x=>x.id===selectedRoom);if(!r)return;markEdit();r.name=document.getElementById('rn').value.trim()||roomNames[r.type];r.type=document.getElementById('rt').value;r.x=Math.max(0,+document.getElementById('rx').value||0);r.y=Math.max(0,+document.getElementById('ry').value||0);r.width=Math.max(.6,+document.getElementById('rw').value||1);r.height=Math.max(.6,+document.getElementById('rh').value||1);r.x=Math.min(r.x,Math.max(0,p.building.length-r.width));r.y=Math.min(r.y,Math.max(0,p.building.width-r.height));dirty=true;recalc();renderPlan();}
function deleteRoom(){markEdit();p.rooms=p.rooms.filter(x=>x.id!==selectedRoom);selectedRoom=null;dirty=true;recalc();renderPlan();}
function renderSpecs(){const opts=(k)=>DATA.materialOptions?.[k]||[];shell('Spesifikasi Rumah','Pilih spesifikasi yang mempengaruhi kebutuhan material, biaya, dan visual.',`<div class="spec-grid">${SpecCard('Dinding','wall',p.spec.wall,opts('wall'))}${SpecCard('Lantai','floor',p.spec.floor,opts('floor'))}${SpecCard('Atap','roofCover',p.spec.roofCover,opts('roofCover'))}${SpecCard('Plafon','ceiling',p.spec.ceiling,opts('ceiling'))}</div><div class="card"><h2>Asumsi Tambahan</h2><div class="formgrid four"><Field id="wm" label="Waste material umum (%)" value={p.waste.material} num/><Field id="wt" label="Waste keramik (%)" value={p.waste.tile} num/><Field id="wp" label="Waste pengecatan (%)" value={p.waste.paint} num/><Field id="wr" label="Waste atap (%)" value={p.waste.roof} num/></div><div class="field" style="margin-top:14px"><label>Model atap</label><select id="roofType"><option value="pelana" ${p.roofType==='pelana'?'selected':''}>Pelana</option><option value="limas" ${p.roofType==='limas'?'selected':''}>Limas</option><option value="datar" ${p.roofType==='datar'?'selected':''}>Datar</option></select></div><div class="actions"><button class="secondary" data-action="gotoStep" data-arg="1">← Denah</button><button class="primary" data-action="applySpecs">Simpan spesifikasi →</button></div></div>`)}
function SpecCard(title,key,val,opts){return `<div class="card spec-card"><h2>${title}</h2><div class="choice-list">${opts.map(o=>`<label class="choice ${val===o.id?'selected':''}"><input type="radio" name="${key}" value="${o.id}" ${val===o.id?'checked':''}><div><b>${o.label}</b><small>${o.note||''}</small></div></label>`).join('')}</div></div>`}
function applySpecs(){for(const k of ['wall','floor','roofCover','ceiling']){const el=document.querySelector(`input[name="${k}"]:checked`);if(el)p.spec[k]=el.value;}p.waste={material:+document.getElementById('wm').value||0,tile:+document.getElementById('wt').value||0,paint:+document.getElementById('wp').value||0,roof:+document.getElementById('wr').value||0,brick:p.waste.brick};p.roofType=document.getElementById('roofType').value;save();step=3;render();}
function renderMaterials(){
 const mats=result.materialRecap||[];
 const q=(document.getElementById('materialSearch')?.value||'').trim().toLowerCase();
 const cat=document.getElementById('materialCategory')?.value||'';
 const categories=[...new Set(mats.map(x=>x.category))];
 const filtered=mats.filter(m=>((!q||`${m.materialName} ${m.materialId}`.toLowerCase().includes(q))&&(!cat||m.category===cat)));
 const rows=filtered.map((m,i)=>`<tr class="material-row" data-material-id="${esc(m.materialId)}"><td>${i+1}</td><td><b>${esc(m.materialName)}</b><div class="muted">${esc(m.materialId)} · ${esc(m.category)}</div></td><td>${m.theoreticalQuantity.toFixed(2)}</td><td>${m.purchaseQuantity.toFixed(2)}</td><td>${esc(m.unit)}</td><td class="num">${money(m.unitPrice)}</td><td class="num"><b>${money(m.totalCost)}</b></td><td><button class="chip" data-action="materialDetail" data-arg="${esc(m.materialId)}">Rincian</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Material tidak ditemukan.</td></tr>';
 const priceRows=Object.entries(requirelessMaterials()).map(([id,d])=>{const price=p.priceOverrides[id]??d[2];const w=p.materialWaste?.[id]??'';return `<tr><td><b>${esc(d[0])}</b><div class="muted">${id}</div></td><td>${d[1]}</td><td><input class="price-input" data-price-id="${id}" type="number" min="0" value="${price}"></td><td><input class="waste-input" data-waste-id="${id}" type="number" min="0" max="100" step="0.1" placeholder="${w===''?'kategori':w}"></td></tr>`}).join('');
 shell('Rekap Material','Akumulasi otomatis berdasarkan material, dengan kebutuhan teoritis, pembelian, sumber pekerjaan, waste, dan biaya.',`
 <div class="summary">${Metric({label:'Jenis material',value:mats.length})}${Metric({label:'Nilai material',value:money(result.summary.material)})}${Metric({label:'Kebutuhan pembelian',value:mats.reduce((a,x)=>a+x.purchaseQuantity,0).toFixed(2)})}</div>
 <div class="card"><div class="toolbar"><div><h2>📦 Rekap Akumulasi Material</h2><p class="muted">Material yang sama digabung berdasarkan materialId. Waste tidak mengubah kebutuhan teoritis.</p></div><div class="button-row"><input id="materialSearch" class="search-input" placeholder="Cari material..." value="${esc(q)}"><select id="materialCategory"><option value="">Semua kategori</option>${categories.map(c=>`<option value="${esc(c)}" ${cat===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="secondary" data-action="filterMaterial">Filter</button></div></div>
 <div class="table-scroll"><table class="rab-table"><tr><th>No</th><th>Material</th><th>Teoritis</th><th>Pembelian</th><th>Satuan</th><th class="num">Harga Satuan</th><th class="num">Estimasi Biaya</th><th></th></tr>${rows}</table></div></div>
 <div id="materialDetailPanel"></div>
 <div class="card"><h2>⚙ Harga & Waste Per Material</h2><p class="muted">Harga dan waste dapat ditimpa khusus proyek. Kosongkan waste untuk memakai default kategori.</p><div class="table-scroll"><table class="rab-table"><tr><th>Material</th><th>Satuan</th><th>Harga</th><th>Waste %</th></tr>${priceRows}</table></div><div class="actions"><button class="primary" data-action="applyPrices">Terapkan harga & waste</button></div></div>
 <div class="actions"><button class="secondary" data-action="gotoStep" data-arg="2">← Spesifikasi</button><button class="primary" data-action="gotoStep" data-arg="4">Lanjut ke RAB →</button></div>`);
}
function requirelessMaterials(){return window.__RAB_MATERIALS||{};} function Metric({label,value}){return `<div class="metric"><span>${label}</span><b>${value}</b></div>`}
async function applyCoefficients(){document.querySelectorAll('[data-coef-id]').forEach(i=>p.coefficients[i.dataset.coefId]=Math.max(0,+i.value||0));await save();render();toast('Koefisien proyek diperbarui.');}
async function applyPrices(){
 document.querySelectorAll('[data-price-id]').forEach(i=>p.priceOverrides[i.dataset.priceId]=Math.max(0,+i.value||0));
 document.querySelectorAll('[data-waste-id]').forEach(i=>{const v=i.value.trim();if(v==='')delete p.materialWaste[i.dataset.wasteId];else p.materialWaste[i.dataset.wasteId]=Math.min(100,Math.max(0,+v||0));});
 await save();renderMaterials();toast('Harga & waste proyek diperbarui.');
}
function materialDetail(id){
 const m=(result.materialRecap||[]).find(x=>x.materialId===id); if(!m)return;
 const panel=document.getElementById('materialDetailPanel'); if(!panel)return;
 panel.innerHTML=`<div class="card"><div class="section-head"><div><h2>🔎 ${esc(m.materialName)}</h2><p class="muted">Total teoritis ${m.theoreticalQuantity.toFixed(2)} ${esc(m.unit)} · pembelian ${m.purchaseQuantity.toFixed(2)} ${esc(m.unit)}</p></div><button class="secondary" data-action="closeMaterialDetail">Tutup</button></div><div class="table-scroll"><table class="rab-table"><tr><th>Pekerjaan</th><th>Komponen</th><th>Teoritis</th><th>Pembelian</th><th>Waste</th><th>Satuan</th></tr>${m.sources.map(s=>`<tr><td>${esc(s.job)}</td><td>${esc(s.component)}</td><td>${s.theoreticalQuantity.toFixed(2)}</td><td>${s.purchaseQuantity.toFixed(2)}</td><td>${s.waste}%</td><td>${esc(s.unit)}</td></tr>`).join('')}</table></div><div class="live-stat"><b>Total biaya material: ${money(m.totalCost)}</b></div></div>`;
}
function closeMaterialDetail(){const x=document.getElementById('materialDetailPanel');if(x)x.innerHTML='';}

function renderRab(){const cats=Object.entries(result.groups);shell('RAB Detail','RAB transparan sampai material dan tenaga kerja. Harga satuan dapat diedit dan disimpan khusus proyek.',`<div class="summary"><div class="metric"><span>Material</span><b>${money(result.summary.material)}</b></div><div class="metric"><span>Tenaga kerja</span><b>${money(result.summary.labor)}</b></div><div class="metric"><span>Peralatan</span><b>${money(result.summary.equipment)}</b></div><div class="metric total-metric"><span>Total RAB</span><b>${money(result.summary.total)}</b></div></div>${cats.map(([cat,items])=>`<div class="card rab-group"><h3>${esc(cat)} <span>${money(items.reduce((a,x)=>a+x.amount,0))}</span></h3><div class="table-scroll"><table class="rab-table"><tr><th>No</th><th>Uraian</th><th>Volume</th><th>Satuan</th><th>Waste</th><th class="num">Harga Satuan</th><th class="num">Jumlah</th></tr>${items.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.description)}${x.kind==='material'?'<div class="muted">Material</div>':'<div class="muted">Tenaga kerja</div>'}</td><td>${x.volume.toFixed(2)}</td><td>${x.unit}</td><td>${x.waste?x.waste+'%':'-'}</td><td class="num"><input class="price-input compact-price" data-rab-price-key="${esc(x.priceKey||'')}" data-rab-price-kind="${x.kind}" type="number" min="0" value="${Math.round(x.unitPrice)}"></td><td class="num"><b>${money(x.amount)}</b></td></tr>`).join('')}</table></div></div>`).join('')}<div class="card"><h2>Rekapitulasi</h2><div class="summary three"><div class="metric"><span>Subtotal langsung</span><b>${money(result.summary.direct)}</b></div><div class="metric"><span>Overhead ${p.extras.overhead}% + contingency ${p.extras.contingency}%</span><b>${money(result.summary.overhead+result.summary.contingency)}</b></div><div class="metric"><span>Biaya per m²</span><b>${money(result.summary.costPerM2)}</b></div></div><div class="formgrid four"><Field id="eq" label="Peralatan (%)" value={p.extras.equipment} num/><Field id="oh" label="Overhead (%)" value={p.extras.overhead} num/><Field id="ct" label="Contingency (%)" value={p.extras.contingency} num/><Field id="pr" label="Profit (%)" value={p.extras.profit} num/><Field id="tr" label="Transportasi (Rp)" value={p.extras.transport} num/></div><div class="actions"><button class="secondary" data-action="applyExtras">Terapkan biaya</button><button class="secondary" data-action="applyRabPrices">💾 Simpan harga satuan</button><button class="primary" data-action="gotoStep" data-arg="5">Lihat Maket 3D →</button></div></div><div class="card budget-card"><h2>🎯 Sesuaikan dengan Dana Tersedia</h2><p class="muted">Pilih mode dana tersedia untuk mendapatkan target anggaran dan saran penghematan. Volume pekerjaan tetap transparan; sistem tidak memalsukan quantity hanya agar total terlihat sesuai dana.</p><div class="formgrid"><div class="field"><label>Mode anggaran</label><select id="budgetMode"><option value="estimate" ${p.budget?.mode==='estimate'?'selected':''}>RAB normal</option><option value="available" ${p.budget?.mode==='available'?'selected':''}>Pakai dana tersedia</option></select></div><Field id="availableFunds" label="Dana tersedia (Rp)" value={p.budget?.availableFunds||0} num/></div><div class="actions"><button class="primary" data-action="applyBudget">Terapkan anggaran</button></div>${result.budgetPlan?.enabled?`<div class="budget-result"><div class="summary three"><div class="metric"><span>Dana tersedia</span><b>${money(result.budgetPlan.availableFunds)}</b></div><div class="metric"><span>RAB normal</span><b>${money(result.summary.total)}</b></div><div class="metric total-metric"><span>Selisih</span><b>${money(result.budgetPlan.gap)}</b></div></div><div class="${result.budgetPlan.feasible?'ok':'warning'}"><b>${result.budgetPlan.feasible?'Dana mencukupi.':'Dana belum mencukupi.'}</b> ${esc(result.budgetPlan.message)}</div>${result.budgetPlan.suggestions.length?`<div class="suggestion-list"><h3>Saran RAB yang bisa diminimalkan</h3>${result.budgetPlan.suggestions.map(s=>`<div class="suggestion"><b>${esc(s.label)}</b><span>Potensi hemat ${money(s.saving)}</span><small>${esc(s.note)}</small></div>`).join('')}</div>`:''}</div>`:''}</div>`)}
async function applyRabPrices(){
 document.querySelectorAll('[data-rab-price-key]').forEach(i=>{const key=i.dataset.rabPriceKey;if(!key)return;const v=Math.max(0,+i.value||0);if(i.dataset.rabPriceKind==='material')p.priceOverrides[key]=v;else p.laborPriceOverrides[key]=v;});
 await save();renderRab();toast('Harga satuan RAB diperbarui.');
}
async function applyBudget(){
 const mode=document.getElementById('budgetMode')?.value||'estimate';
 const available=Math.max(0,+document.getElementById('availableFunds')?.value||0);
 p.budget={...p.budget,mode,availableFunds:available,minimizeSuggestions:true};
 await save();renderRab();toast(mode==='available'?'Mode dana tersedia diterapkan.':'Mode RAB normal diterapkan.');
}
async function applyExtras(){p.extras={equipment:+document.getElementById('eq').value||0,overhead:+document.getElementById('oh').value||0,contingency:+document.getElementById('ct').value||0,profit:+document.getElementById('pr').value||0,transport:+document.getElementById('tr').value||0};await save();renderRab();}
function show3DObject(info){
 const panel=document.getElementById('objectInfo');if(!panel)return;
 if(!info){panel.innerHTML='<h3>Properties</h3><p class="muted">Pilih dinding, pintu, jendela, sekat, ruangan, atau atap. Aktifkan Mode Edit untuk drag.</p>';return;}
 const map={wall:'Dinding',floor:'Lantai',roof:'Atap',column:'Struktur',terrace:'Eksterior',carport:'Eksterior',door:'Kusen/Pintu/Jendela',window:'Kusen/Pintu/Jendela',partition:'Sekat',room:'Ruangan'};
 const cat=map[info.objectType]||info.objectType,items=(result.groups?.[cat]||[]),total=items.reduce((a,x)=>a+x.amount,0);
 let form='';
 if(info.objectType==='wall')form=`<div class="formgrid"><div class="field"><label>Panjang dinding (m)</label><input id="wallLen" type="number" min="3" max="100" step="0.01" value="${(info.axis==='width'?p.building.length:p.building.width).toFixed(2)}"></div><div class="field"><label>Tinggi (m)</label><input id="wallHeightEdit" type="number" min="2.4" max="10" step="0.01" value="${(p.building.wallHeight||3).toFixed(2)}"></div></div><div class="actions"><button class="primary" data-action="applyWallDimension">Simpan Dinding</button><button class="secondary" data-action="addWindowToWall">＋ Tambah Jendela</button></div><p class="muted">Jendela baru otomatis ditempatkan di tengah dinding ini. Posisi dan ukurannya kemudian dapat diedit dari Properties.</p>`;
 if(info.objectType==='door'||info.objectType==='window')form=`<div class="formgrid"><div class="field"><label>Posisi sepanjang dinding (m)</label><input id="openingOffset" type="number" min="0.15" step="0.05" value="${Number(info.offset||0).toFixed(2)}"></div><div class="field"><label>Lebar (m)</label><input id="openingWidth" type="number" min="0.4" step="0.05" value="${Number(info.width||1).toFixed(2)}"></div><div class="field"><label>Tinggi (m)</label><input id="openingHeight" type="number" min="0.5" step="0.05" value="${Number(info.height||1.2).toFixed(2)}"></div>${info.objectType==='window'?`<div class="field"><label>Ambang (m)</label><input id="openingSill" type="number" min="0" step="0.05" value="${Number(info.sillHeight??1).toFixed(2)}"></div>`:''}</div><div class="actions"><button class="primary" data-action="applyOpening">Simpan</button><button class="danger" data-action="deleteOpening">Hapus</button></div>`;
 if(info.objectType==='room'){const rr=p.rooms.find(x=>x.id===info.objectId);if(rr)form=`<div class="formgrid"><div class="field"><label>Nama</label><input id="roomName3D" value="${esc(rr.name)}"></div><div class="field"><label>Panjang (m)</label><input id="roomWidth3D" type="number" min=".6" step=".1" value="${rr.width}"></div><div class="field"><label>Lebar (m)</label><input id="roomHeight3D" type="number" min=".6" step=".1" value="${rr.height}"></div><div class="field"><label>Luas</label><div class="metric">${(rr.width*rr.height).toFixed(2)} m²</div></div></div><div class="actions"><button class="primary" data-action="applyRoom3D">Simpan Ruangan</button><button class="danger" data-action="deleteRoom3D">Hapus</button></div>`;}
if(info.objectType==='roof')form=`<div class="formgrid"><div class="field"><label>Tipe Atap</label><select id="roofTypeEdit">${Object.entries(roofNames).map(([k,v])=>`<option value="${k}" ${p.roofType===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Kemiringan (°)</label><input id="roofPitchEdit" type="number" min="5" max="60" step="1" value="${p.building.roofPitch||30}"></div><div class="field"><label>Overhang (m)</label><input id="roofOverhangEdit" type="number" min="0.05" max="2" step=".05" value="${p.building.overhang||.5}"></div><div class="field"><label>Material</label><input value="${esc(p.spec?.roofCover||'')}" disabled></div></div><div class="actions"><button class="primary" data-action="applyRoof">Simpan Atap</button></div>`;
if(info.objectType==='partition')form=`<div class="formgrid"><div class="field"><label>Panjang sekat (m)</label><input id="partitionLength" type="number" min=".6" step=".05" value="${Number(info.length||2).toFixed(2)}"></div></div><div class="actions"><button class="primary" data-action="applyPartition">Simpan Sekat</button><button class="danger" data-action="deletePartition">Hapus</button></div>`;
 let dimensions='';
 if(info.objectType==='floor')dimensions=`<div class="mini-list"><div><span>Luas lantai</span><b>${result.geometry.floorArea.toFixed(2)} m²</b></div></div>`;
 if(info.objectType==='roof')dimensions=`<div class="mini-list"><div><span>Luas atap estimasi</span><b>${result.geometry.roofArea.toFixed(2)} m²</b></div><div><span>Kemiringan</span><b>${p.building.roofPitch}°</b></div><div><span>Overhang</span><b>${p.building.overhang} m</b></div></div>`;
 panel.innerHTML=`<h3>${esc(info.objectName||cat)}</h3><p class="muted">Jenis: ${esc(cat)} · ID: ${esc(info.objectId||'-')}</p>${dimensions}${form}${items.length?`<div class="object-total">Biaya terkait: <b>${money(total)}</b></div><h4>RAB & Material</h4><div class="mini-list">${items.map(x=>`<div><span>${esc(x.description)}</span><b>${x.volume.toFixed(2)} ${esc(x.unit)}</b></div>`).join('')}</div>`:'<p class="muted">Belum ada item RAB yang dapat dipetakan langsung ke objek ini.</p>'}`;
}
function applyRoom3D(){const info=window.__selectedHouseObject,r=p.rooms.find(x=>x.id===info?.objectId);if(!r)return;markEdit();r.name=document.getElementById('roomName3D').value.trim()||r.name;r.width=Math.max(.6,+document.getElementById('roomWidth3D').value||r.width);r.height=Math.max(.6,+document.getElementById('roomHeight3D').value||r.height);r.x=Math.min(r.x,Math.max(0,p.building.length-r.width));r.y=Math.min(r.y,Math.max(0,p.building.width-r.height));setDirty(true);render();}
function deleteRoom3D(){const info=window.__selectedHouseObject;if(!info)return;markEdit();p.rooms=p.rooms.filter(x=>x.id!==info.objectId);window.__selectedHouseObject=null;setDirty(true);render();}
function applyRoof(){if(!p)return;markEdit();p.roofType=document.getElementById('roofTypeEdit')?.value||p.roofType;p.building.roofPitch=Math.max(5,Math.min(60,+document.getElementById('roofPitchEdit')?.value||30));p.building.overhang=Math.max(.05,Math.min(2,+document.getElementById('roofOverhangEdit')?.value||.5));setDirty(true);render();}
function addWindowToWall(){
 const info=window.__selectedHouseObject;if(!info||info.objectType!=='wall'||!p)return;
 markEdit();
 const wallId=info.objectId;
 const wallLen=info.axis==='width'?+p.building.length:+p.building.width;
 const width=Math.min(1.2,Math.max(.8,wallLen-.4));
 const o={id:'window-'+Date.now().toString(36)+'-'+Math.random().toString(16).slice(2,7),type:'window',wallId,offset:wallLen/2,width,height:1.2,sillHeight:1,rotation:info.axis==='width'?0:Math.PI/2};
 clampOpening(o);p.windows.push(o);syncOpeningCounts();setDirty(true);render();
}
function openingList(type){return type==='door'?p.doors:p.windows;}
function syncOpeningCounts(){p.building.openings.doors=p.doors.length;p.building.openings.windows=p.windows.length;}
function clampOpening(o){const wallLen=['wall-left','wall-right'].includes(o.wallId)?p.building.width:p.building.length;o.width=Math.min(Math.max(.4,Number(o.width)||.9),Math.max(.4,wallLen-.02));o.offset=Math.max(o.width/2,Math.min(wallLen-o.width/2,Number(o.offset)||wallLen/2));o.height=Math.max(.5,Number(o.height)||1.2);if(o.type==='door')o.sillHeight=0;else o.sillHeight=Math.max(0,Number(o.sillHeight)||1);return o;}
function clampPartition(q){const L=p.building.length,W=p.building.width;q.length=Math.min(Math.max(.6,Number(q.length)||.6),q.axis==='y'?Math.max(.6,W-.2):Math.max(.6,L-.2));q.x=Math.max(0,Math.min(L,q.x));q.y=Math.max(0,Math.min(W,q.y));if(q.axis==='x')q.x=Math.max(q.length/2,Math.min(L-q.length/2,q.x));else q.y=Math.max(q.length/2,Math.min(W-q.length/2,q.y));return q;}
function applyPlanOpening(){const info=selectedPlanObject;if(!info||!['door','window'].includes(info.type))return;const arr=openingList(info.type),o=arr.find(x=>x.id===info.id);if(!o)return;markEdit();o.wallId=document.getElementById('poWall').value;o.offset=+document.getElementById('poOffset').value||o.offset;o.width=+document.getElementById('poWidth').value||o.width;o.height=+document.getElementById('poHeight').value||o.height;if(document.getElementById('poSill'))o.sillHeight=+document.getElementById('poSill').value||o.sillHeight||1;clampOpening(o);syncOpeningCounts();setDirty(true);renderPlan();}
function deletePlanOpening(){const info=selectedPlanObject;if(!info||!['door','window'].includes(info.type))return;markEdit();const key=info.type==='door'?'doors':'windows';p[key]=p[key].filter(x=>x.id!==info.id);syncOpeningCounts();selectedPlanObject=null;setDirty(true);renderPlan();}
function applyPlanPartition(){const info=selectedPlanObject,q=p.partitions.find(x=>x.id===info?.id);if(!q)return;markEdit();q.x=Math.max(0,+document.getElementById('poX').value||q.x);q.y=Math.max(0,+document.getElementById('poY').value||q.y);q.length=Math.max(.6,+document.getElementById('poLen').value||q.length);q.axis=document.getElementById('poAxis').value;setDirty(true);renderPlan();}
function applyOpening(){
 const info=window.__selectedHouseObject;if(!info||!['door','window'].includes(info.objectType))return;
 const arr=openingList(info.objectType),o=arr.find(x=>x.id===info.objectId);if(!o)return;markEdit();
 o.offset=+document.getElementById('openingOffset').value||o.offset;
 o.width=+document.getElementById('openingWidth').value||o.width;
 o.height=+document.getElementById('openingHeight').value||o.height;
 const sill=document.getElementById('openingSill');if(sill)o.sillHeight=+sill.value||o.sillHeight||1;clampOpening(o);
 syncOpeningCounts();setDirty(true);render();
}
function deleteOpening(){const info=window.__selectedHouseObject;if(!info||!['door','window'].includes(info.objectType))return;markEdit();const key=info.objectType==='door'?'doors':'windows';p[key]=p[key].filter(x=>x.id!==info.objectId);syncOpeningCounts();window.__selectedHouseObject=null;render();}
function commit3DOpeningChange(v){if(!p||!v)return;const arr=openingList(v.objectType),o=arr.find(x=>x.id===v.objectId);if(!o)return;o.offset=+v.offset||o.offset;clampOpening(o);syncOpeningCounts();setDirty(true);render();}
function add3DOpening(type){
 markEdit();const b=p.building||{},L=+b.length||6,W=+b.width||6,key=type==='door'?'doors':'windows',n=p[key].length;
 p[key].push({id:`${type}-${String(Date.now()).slice(-6)}-${n+1}`,type,wallId:'wall-front',offset:L/2,width:type==='door'?(+b.openings?.doorWidth||.9):(+b.openings?.windowWidth||1.2),height:type==='door'?(+b.openings?.doorHeight||2.1):(+b.openings?.windowHeight||1.2),sillHeight:type==='door'?0:1,rotation:0});
 clampOpening(p[key][p[key].length-1]);syncOpeningCounts();setDirty(true);render();
}
function commit3DPartitionChange(v){const q=p?.partitions?.find(x=>x.id===v?.objectId);if(!q)return;q.x=(+v.x||0)+p.building.length/2;q.y=(+v.z||0)+p.building.width/2;clampPartition(q);setDirty(true);render();}
function addPartition(){
 markEdit();const b=p.building||{},i=p.partitions.length;p.partitions.push({id:`partition-${Date.now()}`,name:`Sekat ${i+1}`,axis:'x',x:(+b.length||6)/2,y:(+b.width||6)/2,length:Math.min(3,(+b.length||6)-.4),roomA:null,roomB:null});setDirty(true);render();
}
function applyPartition(){const info=window.__selectedHouseObject,q=p.partitions.find(x=>x.id===info?.objectId);if(!q)return;markEdit();q.length=+document.getElementById('partitionLength').value||q.length;clampPartition(q);setDirty(true);render();}
function deletePartition(){if(selectedPlanObject?.type==='partition'){markEdit();p.partitions=p.partitions.filter(x=>x.id!==selectedPlanObject.id);selectedPlanObject=null;setDirty(true);renderPlan();return;}const info=window.__selectedHouseObject;if(!info||info.objectType!=='partition')return;markEdit();p.partitions=p.partitions.filter(x=>x.id!==info.objectId);window.__selectedHouseObject=null;setDirty(true);render();}
function resizeRoomsForWall(info,oldL,oldW,newL,newW){const eps=.08,dL=newL-oldL,dW=newW-oldW;(p.rooms||[]).forEach(r=>{if(info.axis==='width'&&Math.abs(dW)>eps){const touches=info.objectId==='wall-front'?r.y<=eps:(r.y+r.height)>=oldW-eps;if(touches)r.height=Math.max(.6,r.height+dW);}if(info.axis==='length'&&Math.abs(dL)>eps){const touches=info.objectId==='wall-left'?r.x<=eps:(r.x+r.width)>=oldL-eps;if(touches)r.width=Math.max(.6,r.width+dL);}});}
function applyWallDimension(){const info=window.__selectedHouseObject;if(!info||info.objectType!=='wall')return;const len=Math.max(3,Math.min(100,+document.getElementById('wallLen').value||0));const heightEl=document.getElementById('wallHeightEdit');const height=heightEl?Math.max(2.4,Math.min(10,+heightEl.value||p.building.wallHeight||3)):p.building.wallHeight||3;markEdit();const oldL=p.building.length,oldW=p.building.width,newL=info.axis==='width'?len:oldL,newW=info.axis==='length'?len:oldW;resizeRoomsForWall(info,oldL,oldW,newL,newW);p.building.length=newL;p.building.width=newW;p.building.wallHeight=height;p.building.area=newL*newW*p.building.floors;clampRoomsToBuilding();dirty=true;render();}
function clampRoomsToBuilding(){(p.rooms||[]).forEach(r=>{r.width=Math.min(r.width,Math.max(.6,p.building.length));r.height=Math.min(r.height,Math.max(.6,p.building.width));r.x=Math.min(Math.max(0,r.x),Math.max(0,p.building.length-r.width));r.y=Math.min(Math.max(0,r.y),Math.max(0,p.building.width-r.height));});}
function commit3DWallChange(v){if(!p||!v)return;const info=v.wall,oldL=p.building.length,oldW=p.building.width,newL=+v.length,newW=+v.width;if(Math.abs(newL-oldL)<.001&&Math.abs(newW-oldW)<.001)return;resizeRoomsForWall(info,oldL,oldW,newL,newW);p.building.length=newL;p.building.width=newW;p.building.area=newL*newW*p.building.floors;clampRoomsToBuilding();setDirty(true);render();}
