function applyVisualColor(){const key=document.getElementById('visualColorKey')?.value;if(!key)return;markEdit();p.visual=p.visual||{colors:{}};p.visual.colors=p.visual.colors||{};p.visual.colors[key]=document.getElementById('visualColor')?.value||'#FFFFFF';p.visual.preset='custom';dirty=true;render();}
function applyColorPreset(name){const preset=colorPresets[name];if(!preset)return;markEdit();p.visual=p.visual||{};p.visual.colors={...p.visual.colors,...preset};p.visual.preset=name;dirty=true;render();}
