async function doPdf(){const f=await window.api.exportPdf({project:p,result});if(f)toast('PDF berhasil dibuat.');} async function doExcel(){const f=await window.api.exportExcel({project:p,result});if(f)toast('Excel berhasil dibuat.');} async function doExport(){const f=await window.api.exportProject(p);if(f)toast('Backup project berhasil dibuat.');} async function doImport(){const x=await window.api.importProject();if(x){p=normalize(x);step=0;await save();render();toast('Project berhasil diimport.');}}
