appEl.addEventListener('mousedown',e=>{const obj=e.target.closest('[data-plan-object]');if(obj){const [type,id]=obj.dataset.planObject.split(':');const arr=type==='door'?p.doors:type==='window'?p.windows:p.partitions,q=arr.find(x=>x.id===id);if(!q)return;selectedPlanObject={type,id};selectedRoom=null;markEdit();const plan=document.getElementById('plan'),rect=plan.getBoundingClientRect(),scale=rect.width/p.building.length;window.__planDrag={type,id,q,rect,scale};e.preventDefault();return;}const el=e.target.closest('.room');if(!el)return;const r=p.rooms.find(x=>x.id===el.dataset.roomId);if(!r)return;selectedRoom=r.id;selectedPlanObject=null;markEdit();const plan=document.getElementById('plan'),rect=plan.getBoundingClientRect(),scale=rect.width/p.building.length;window.__drag={r,ox:e.clientX-rect.left-r.x*scale,oy:e.clientY-rect.top-r.y*scale,rect,scale};e.preventDefault();});
